Map<Integer, List<int[]>> graph = new HashMap<>();
graph.put(1, List.of(new int[]{2, 4}, new int[]{3, 1}));
graph.put(2, List.of(new int[]{4, 1}));
graph.put(3, List.of(new int[]{2, 1}, new int[]{4, 5}));
graph.put(4, List.of());

int source = 1;
Map<Integer, Integer> dist = new HashMap<>();
for (int node : graph.keySet()) dist.put(node, Integer.MAX_VALUE);
dist.put(source, 0);

PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(e -> e[1]));
pq.offer(new int[]{source, 0});
Set<Integer> visited = new HashSet<>();

while (!pq.isEmpty()) {
    int[] current = pq.poll();
    int node = current[0], d = current[1];
    if (!visited.add(node)) continue;
    for (int[] edge : graph.getOrDefault(node, List.of())) {
        int neighbor = edge[0], weight = edge[1];
        if (d + weight < dist.get(neighbor)) {
            dist.put(neighbor, d + weight);
            pq.offer(new int[]{neighbor, d + weight});
        }
    }
}
System.out.println("Najkrotsze dystanse od " + source + ": " + dist);

class MedianFinder {
    private final PriorityQueue<Integer> lowerHalf = new PriorityQueue<>(Comparator.reverseOrder()); // max-heap
    private final PriorityQueue<Integer> upperHalf = new PriorityQueue<>(); // min-heap

    void addNum(int num) {
        lowerHalf.offer(num);
        upperHalf.offer(lowerHalf.poll());
        if (upperHalf.size() > lowerHalf.size()) {
            lowerHalf.offer(upperHalf.poll());
        }
    }

    double findMedian() {
        if (lowerHalf.size() > upperHalf.size()) return lowerHalf.peek();
        return (lowerHalf.peek() + upperHalf.peek()) / 2.0;
    }
}

MedianFinder finder = new MedianFinder();
for (int n : new int[]{5, 15, 1, 3, 8}) {
    finder.addNum(n);
    System.out.println("Po dodaniu " + n + ", mediana: " + finder.findMedian());
}

