int time = 0;
Queue<int[]> cooldownQueue = new LinkedList<>(); // {pozostala liczba, dostepny_od}
while (!maxHeap.isEmpty() || !cooldownQueue.isEmpty()) {
    time++;
    if (!maxHeap.isEmpty()) {
