class KthLargest {
    private final int k;
    private final PriorityQueue<Integer> minHeap = new PriorityQueue<>();

    KthLargest(int k, int[] initialNumbers) {
        this.k = k;
        for (int n : initialNumbers) add(n);
    }

    int add(int val) {
        minHeap.offer(val);
        if (minHeap.size() > k) minHeap.poll();
        return minHeap.peek();
    }
}

