for (int val : new int[]{3, 5, 10, 9, 4}) {
    System.out.println("Po dodaniu " + val + ", 3-ci najwiekszy: " + kth.add(val));
}

static String reorganizeString(String s) {
    Map<Character, Integer> counts = new HashMap<>();
    for (char c : s.toCharArray()) counts.merge(c, 1, Integer::sum);

    PriorityQueue<Map.Entry<Character, Integer>> maxHeap = new PriorityQueue<>(
        Map.Entry.<Character, Integer>comparingByValue().reversed()
    );
    maxHeap.addAll(counts.entrySet());

    StringBuilder result = new StringBuilder();
    Map.Entry<Character, Integer> previous = null;
    while (!maxHeap.isEmpty()) {
        Map.Entry<Character, Integer> current = maxHeap.poll();
        result.append(current.getKey());
        current.setValue(current.getValue() - 1);
        if (previous != null && previous.getValue() > 0) {
            maxHeap.offer(previous);
        }
        previous = current;
    }
    return result.length() == s.length() ? result.toString() : "BRAK ROZWIAZANIA";
}

