Map<Integer, List<int[]>> graph = new HashMap<>();
graph.put(1, List.of(new int[]{2, 1}, new int[]{3, 4}));
graph.put(2, List.of(new int[]{1, 1}, new int[]{3, 2}, new int[]{4, 5}));
graph.put(3, List.of(new int[]{1, 4}, new int[]{2, 2}, new int[]{4, 1}));
graph.put(4, List.of(new int[]{2, 5}, new int[]{3, 1}));

int start = 1;
Set<Integer> visited = new HashSet<>();
PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(e -> e[0])); // {waga, wezel}
pq.offer(new int[]{0, start});
int totalWeight = 0;

while (!pq.isEmpty() && visited.size() < graph.size()) {
    int[] current = pq.poll();
    int weight = current[0], node = current[1];
    if (!visited.add(node)) continue;
    totalWeight += weight;
    for (int[] edge : graph.getOrDefault(node, List.of())) {
        if (!visited.contains(edge[0])) {
            pq.offer(new int[]{edge[1], edge[0]});
        }
    }
}
System.out.println("Laczna waga MST: " + totalWeight);
